#!/usr/bin/env bash
# Render the shipped shell in Chromium. Only these temporary copies contain a mock camera.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
DEST="${RUNNER_TEMP:-/tmp}/tawel-ui-preview"
mkdir -p "$DEST"
cp "$ROOT"/spike/mac.{html,css,js} "$DEST/"
cp "$ROOT"/spike/mac-i18n.js "$ROOT"/spike/diagnostics.js "$DEST/"
python3 - "$DEST" <<'PY'
from pathlib import Path
import sys
folder=Path(sys.argv[1]); html=(folder/'mac.html').read_text()
mock='''<script>window.__TAURI__={core:{invoke:async function(command){if(command==='native_preview')return JSON.stringify({image:'',width:640,height:480,mouth:[[.45,.6],[.5,.58],[.55,.6],[.5,.62]],center:[.5,.6],chains:[[[.2,.2],[.3,.35],[.4,.45],[.48,.56]]],tips:[[.48,.56]]});if(command==='native_sound_settings')return JSON.stringify({enabled:true,preset:2,volume:0.35});if(command==='native_review')return JSON.stringify({today:'2026-10-02',yesterday:'2026-10-01',days:{'2026-10-02':{moments:3,observedSeconds:3600,longestQuietSeconds:1250,hourly:Array.from({length:24},(_,i)=>i===10?2:i===14?1:0)}}});if(command==='native_snapshot')return {enabled:true,status:2,camera:'Microsoft LifeCam HD-3000',hintActive:false,snoozeUntil:null};return null;}},event:{listen:async function(){}}};</script>'''
for name in ['focus','settings','review','hints','animation','camera']:
    check='''<script>window.addEventListener('load',()=>{TAB;setTimeout(()=>{document.documentElement.dataset.layout= document.documentElement.scrollWidth<=innerWidth ? 'pass' : 'overflow';},100);});</script>'''.replace('TAB',"document.getElementById('settingsTab').click();document.getElementById('"+name+"Section').click()" if name in ['hints','animation','camera'] else "document.getElementById('"+name+"Tab').click()" if name!='focus' else '')
    (folder/(name+'.html')).write_text(html.replace('<script src="./diagnostics.js">',mock+'<script src="./diagnostics.js">').replace('</body>',check+'</body>'))
PY
# Bounded browser session. Chromium CLI can wait indefinitely on macOS runners.
npm install --prefix "$DEST" --no-audit --no-fund playwright@1.58.2
"$DEST/node_modules/.bin/playwright" install --with-deps chromium
node - "$DEST" <<'JS'
const path = require('node:path');
const fs = require('node:fs');
const {pathToFileURL} = require('node:url');
const dest = process.argv[2];
const {chromium} = require(path.join(dest, 'node_modules/playwright'));
(async () => {
  const browser = await chromium.launch({headless:true, timeout:30000});
  const errors=[];
  try {
    for (const view of ['focus','settings','review','hints','animation','camera']) {
      const page = await browser.newPage({viewport:{width:680,height:800}, locale:'de-AT'});
      await page.goto(pathToFileURL(path.join(dest, view+'.html')).href, {waitUntil:'domcontentloaded',timeout:15000});
      await page.waitForFunction(() => document.documentElement.dataset.layout === 'pass', null, {timeout:10000});
      await page.getByRole('button', {name:'Pausieren',exact:true,includeHidden:true}).waitFor({state:'attached',timeout:10000});
      if (!(await page.content()).includes('Microsoft LifeCam HD-3000')) throw Error('Native state missing');
      for (const size of [{width:680,height:800},{width:520,height:760}]) {
        await page.setViewportSize(size);
        const overflow = await page.evaluate(() => ({x:document.documentElement.scrollWidth-innerWidth,y:document.documentElement.scrollHeight-innerHeight}));
        if (overflow.x > 1 || overflow.y > 1) errors.push(view+' overflow at '+JSON.stringify(size)+': '+JSON.stringify(overflow));
      }
      await page.setViewportSize({width:680,height:800});
      await page.screenshot({path:path.join(dest,view+'.png'),fullPage:true});
      if (view === 'camera') {
        await page.getByRole('switch').check();
        await page.locator('#cameraFrame').waitFor({state:'visible',timeout:10000});
        const fits = await page.locator('#cameraFrame').evaluate(el => {
          const a=el.getBoundingClientRect(), b=el.parentElement.getBoundingClientRect();
          return a.top>=b.top && a.bottom<=b.bottom && a.left>=b.left && a.right<=b.right && Math.abs(a.width/a.height-4/3)<.01;
        });
        if(!fits) throw Error('Preview is cropped or distorted');
        if(await page.locator('#cameraLandmarks circle').count() !== 5) throw Error('Missing preview landmarks');
        await page.screenshot({path:path.join(dest,'camera-preview.png'),fullPage:true});
        await page.locator('#focusTab').click();
        await page.locator('#cameraFrame').waitFor({state:'hidden',timeout:1000});
      }
      if (view === 'settings') {
        await page.emulateMedia({colorScheme:'dark'});
        await page.screenshot({path:path.join(dest,'settings-dark.png'),fullPage:true});
      }
      await page.close();
    }
    if(errors.length) throw Error(errors.join('\n'));
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode=1; });
JS
